details.command:
kubectl exec -n default probeinsp -- sh -c 'nginx -g "daemon off;" & sleep 3; echo "== / =="; curl -s -o /dev/null -w "%{http_code}
" http://127.0.0.1:80/; echo "== /healthz =="; curl -s -o /dev/null -w "%{http_code}
" http://127.0.0.1:80/healthz; echo "== :8080 =="; curl -s -o /dev/null -w "%{http_code}
" --max-time 2 http://127.0.0.1:8080/healthz || echo "connection refused/err"; echo "== listeners =="; grep -E "^\s*listen" /etc/nginx/conf.d/default.conf' 2>&1
